fn append(v: &Vec<u64>, elem: u64) -> Vec<u64> {
    // Pre-allocate a new Vec with capacity for all original elements plus one.
    let mut result = Vec::with_capacity(v.len() + 1);

    // Copy over all elements from the original Vec.
    result.extend_from_slice(v);

    // Append the new element.
    result.push(elem);

    result
}

