    #[test]
    fn test_append_nonempty() {
        let v = vec![1, 2, 3];
        let out = append(&v, 99);
        assert_eq!(out, vec![1, 2, 3, 99]);
        // Original vector is unchanged
        assert_eq!(v, vec![1, 2, 3]);
    }

    #[test]
    fn test_append_multiple() {
        let v = vec![10, 20];
        let out1 = append(&v, 30);
        let out2 = append(&out1, 40);
        assert_eq!(out1, vec![10, 20, 30]);
        assert_eq!(out2, vec![10, 20, 30, 40]);
    }
